class TeamData:
    def __init__(self, name: str, capacity: int):
        self.id = str(uuid.uuid4())
        self.name = name
        self.capacity = capacity
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.todos: Dict[int, Todo] = {}
        self.next_todo_id = 1
        self.lock = threading.Lock()

    @property
    def todo_count(self) -> int:
        return len(self.todos)

    @property
    def completed_count(self) -> int:
        return sum(1 for t in self.todos.values() if t.completed)


teams: Dict[str, TeamData] = {}
teams_lock = threading.Lock()

rate_limits: Dict[str, list] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100


# ============== HELPERS ==============

def _check_rate_limit(team_id: str) -> bool:
    """Returns True if rate limit exceeded, False otherwise."""
    now = time.time()
    with rate_limit_lock:
        # Clean old entries
        rate_limits[team_id] = [t for t in rate_limits[team_id] if now - t < 60]
        if len(rate_limits[team_id]) >= RATE_LIMIT:
            return True
        rate_limits[team_id].append(now)
        return False


def _validate_team(team_id: str) -> Optional[TeamData]:
    """Validate and return team, or None."""
    with teams_lock:
        return teams.get(team_id)


def _validate_title(title: Optional[str]) -> Optional[str]:
    """Validate title. Returns error message or None."""
    if title is None:
        return "Missing title"
    if not isinstance(title, str):
        return "Invalid title"
    stripped = title.strip()
    if len(stripped) == 0:
        return "Empty title"
    if len(title) > 1000:
        return "Title too long"
    if _detect_sql_injection(title):
        return "SQL injection detected"
    return None


def _detect_sql_injection(text: str) -> bool:
    """Detect SQL injection patterns."""
    if not text or not isinstance(text, str):
        return False

    text_lower = text.lower()

    # Patterns that indicate SQL injection attempts
    dangerous_patterns = [
        r"['\"]?\s*;\s*\w",           # semicolon after quote
        r"'\s*or\s+",                  # ' OR
        r"'\s*and\s+",                # ' AND
        r"'\s*union\s+",              # ' UNION
        r"'\s*drop\s+",               # ' DROP
        r"'\s*select\s+",             # ' SELECT
        r"\bdrop\s+table\b",          # DROP TABLE
        r"\bselect\s+\*\s+from\b",    # SELECT * FROM
        r"\bunion\s+select\b",        # UNION SELECT
        r"'\s*or\s+'[^']*'\s*=\s*'[^']*'",  # 'OR 'x'='y'
        r"'\s*or\s+\d+=\d+",         # ' OR 1=1
    ]

    for pattern in dangerous_patterns:
        if re.search(pattern, text_lower):
            return True

    return False


def _validate_tags(tags: Optional[List]) -> Optional[str]:
    """Validate tags."""
    if tags is None:
        return None
    if not isinstance(tags, list):
        return "Tags must be an array"
    for tag in tags:
        if not isinstance(tag, str):
            return "Each tag must be a string"
        if len(tag) > 100:
            return "Tag too long"
    return None


def _validate_metadata(metadata: Optional[Any]) -> Optional[str]:
    """Validate metadata."""
    if metadata is None:
        return None
    if not isinstance(metadata, dict):
        return "Metadata must be an object"
    return None


