@app.route('/teams', methods=['POST'])
def create_team():
    # Validate JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    # Validate name
    name = data.get("name")
    if not name or not isinstance(name, str):
        return jsonify({"error": "Bad request", "message": "Missing name"}), 400
    if name.strip() == "":
        return jsonify({"error": "Bad request", "message": "Empty name"}), 400

    # Validate capacity
    capacity = data.get("capacity")
    if capacity is None:
        return jsonify({"error": "Bad request", "message": "Missing capacity"}), 400
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        return jsonify({"error": "Bad request", "message": "Invalid capacity"}), 400
    if capacity <= 0:
        return jsonify({"error": "Bad request", "message": "Invalid capacity"}), 400

    with teams_lock:
        team = TeamData(name, capacity)
        teams[team.id] = team

    return jsonify({
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201


@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    # Check auth - team_id in header must match team_id in URL
    header_team_id = request.headers.get('X-Team-ID')
    if not header_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team = _validate_team(header_team_id)
    if not team:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    # Check if team_id in URL matches the authenticated team
    if header_team_id != team_id:
        return jsonify({"error": "Forbidden", "message": "Access denied"}), 403

    # Also verify the URL team_id exists and matches
    url_team = _validate_team(team_id)
    if not url_team or url_team.id != header_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    with team.lock:
        total = len(team.todos)
        completed = sum(1 for t in team.todos.values() if t.completed)
        if team.capacity > 0:
            pct = (total / team.capacity) * 100
        else:
            pct = 0.0
        capacity_used = f"{pct:.1f}%"

    return jsonify({
        "total_todos": total,
        "completed": completed,
        "capacity_used": capacity_used
    }), 200


@app.route('/todos', methods=['GET'])
def get_todos():
    team = g.team

    # Parse pagination
    page_str = request.args.get('page', '1')
    try:
        page = int(page_str)
    except (ValueError, TypeError):
        return jsonify({"error": "Bad request", "message": "Invalid page number"}), 400
    if page < 1:
        return jsonify({"error": "Bad request", "message": "Invalid page number"}), 400

    # Parse filters
    completed_filter = request.args.get('completed')
    if completed_filter is not None:
        if completed_filter.lower() == 'true':
            completed_filter = True
        elif completed_filter.lower() == 'false':
            completed_filter = False
        else:
            return jsonify({"error": "Bad request", "message": "Invalid completed filter"}), 400

    tag_filter = request.args.get('tag')

    # Parse sort
    sort_param = request.args.get('sort', 'created_asc')
    valid_sorts = ['created_asc', 'created_desc', 'title']
    if sort_param not in valid_sorts:
        return jsonify({"error": "Bad request", "message": "Invalid sort parameter"}), 400

    with team.lock:
        todos_list = list(team.todos.values())

    # Apply filters
    if completed_filter is not None:
        todos_list = [t for t in todos_list if t.completed == completed_filter]
    if tag_filter:
        todos_list = [t for t in todos_list if tag_filter in t.tags]

    # Apply sorting
    if sort_param == 'created_asc':
        todos_list.sort(key=lambda t: (t.created_at, t.id))
    elif sort_param == 'created_desc':
        todos_list.sort(key=lambda t: (t.created_at, t.id), reverse=True)
    elif sort_param == 'title':
        todos_list.sort(key=lambda t: t.title)

    total = len(todos_list)
    page_size = 50

    # Apply pagination
    start = (page - 1) * page_size
    end = start + page_size
    page_todos = todos_list[start:end]

    next_cursor = page + 1 if end < total else None

    return jsonify({
        "todos": [t.to_dict() for t in page_todos],
        "page": page,
        "page_size": len(page_todos),
        "next_cursor": next_cursor,
        "total": total
    }), 200


@app.route('/todos', methods=['POST'])
def create_todo():
    team = g.team

    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    # Validate title
    title = data.get("title")
    title_err = _validate_title(title)
    if title_err:
        return jsonify({"error": "Bad request", "message": title_err}), 400

    # Validate optional fields
    completed = data.get("completed", False)
    if not isinstance(completed, bool):
        return jsonify({"error": "Bad request", "message": "Invalid completed field"}), 400

    tags = data.get("tags")
    tags_err = _validate_tags(tags)
    if tags_err:
        return jsonify({"error": "Bad request", "message": tags_err}), 400

    metadata = data.get("metadata")
    meta_err = _validate_metadata(metadata)
    if meta_err:
        return jsonify({"error": "Bad request", "message": meta_err}), 400

    with team.lock:
        # Check capacity
        if len(team.todos) >= team.capacity:
            return jsonify({
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": len(team.todos)
            }), 403

        todo_id = team.next_todo_id
        team.next_todo_id += 1

        todo = Todo(
            id=todo_id,
            title=title,
            team_id=team.id,
            completed=completed,
            tags=tags if tags is not None else [],
            metadata=metadata if metadata is not None else {}
        )
        team.todos[todo_id] = todo
        result = todo.to_dict()

    return jsonify(result), 201


