    return jsonify(todo.to_dict()), 200


@app.route('/todos/<int:todo_id>', methods=['PUT'])
def update_todo(todo_id):
    team = g.team

    # Check X-If-Version header
    version_header = request.headers.get('X-If-Version')
    if not version_header:
        return jsonify({"error": "Bad request", "message": "Missing X-If-Version header"}), 400

    try:
        provided_version = int(version_header)
    except (ValueError, TypeError):
        return jsonify({"error": "Bad request", "message": "Invalid version"}), 400

    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    with team.lock:
        todo = team.todos.get(todo_id)

        if not todo or todo.team_id != team.id:
            return jsonify({"error": "Todo not found"}), 404

        if todo.version != provided_version:
            return jsonify({
                "error": "Version mismatch",
                "current_version": todo.version,
                "provided_version": provided_version
            }), 409

        # Validate title if provided
        if "title" in data:
            title_err = _validate_title(data["title"])
            if title_err:
                return jsonify({"error": "Bad request", "message": title_err}), 400

        # Validate tags if provided
        if "tags" in data:
            tags_err = _validate_tags(data["tags"])
            if tags_err:
                return jsonify({"error": "Bad request", "message": tags_err}), 400

        # Validate metadata if provided
        if "metadata" in data:
            meta_err = _validate_metadata(data["metadata"])
            if meta_err:
                return jsonify({"error": "Bad request", "message": meta_err}), 400

        # Apply updates
        if "title" in data:
            todo.title = data["title"]
        if "completed" in data:
            if not isinstance(data["completed"], bool):
                return jsonify({"error": "Bad request", "message": "Invalid completed field"}), 400
            todo.completed = data["completed"]
        if "tags" in data:
            todo.tags = data["tags"]
        if "metadata" in data:
            todo.metadata = data["metadata"]

        todo.version += 1
        todo.updated_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        result = todo.to_dict()

    return jsonify(result), 200


@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    team = g.team

    with team.lock:
        todo = team.todos.get(todo_id)

        if not todo or todo.team_id != team.id:
            return jsonify({"error": "Todo not found"}), 404

        del team.todos[todo_id]

    return jsonify({"id": todo_id, "deleted": True}), 200


@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    team = g.team

    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    if "updates" not in data:
        return jsonify({"error": "Bad request", "message": "Missing updates field"}), 400

    updates = data["updates"]
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request", "message": "Updates must be an array"}), 400

    if len(updates) > 100:
        return jsonify({"error": "Bad request", "message": "Too many updates"}), 400

    # Validate all update items
    for item in updates:
        if not isinstance(item, dict):
            return jsonify({"error": "Bad request", "message": "Invalid update item"}), 400
        if "id" not in item:
            return jsonify({"error": "Bad request", "message": "Missing id in update item"}), 400

    # Empty batch
    if len(updates) == 0:
        return jsonify({"updated": [], "count": 0}), 200

    # Atomic batch update
    with team.lock:
        # First, validate all todos exist and belong to team
        todos_to_update = []
        for item in updates:
            tid = item["id"]
            if not isinstance(tid, int):
                return jsonify({"error": "Bad request", "message": "Invalid todo id"}), 400
            todo = team.todos.get(tid)
            if not todo or todo.team_id != team.id:
                return jsonify({"error": "Todo not found"}), 404
            todos_to_update.append((todo, item))

        # Validate all updates
        for todo, item in todos_to_update:
            if "title" in item:
                title_err = _validate_title(item["title"])
                if title_err:
                    return jsonify({"error": "Bad request", "message": title_err}), 400
            if "tags" in item:
                tags_err = _validate_tags(item["tags"])
                if tags_err:
                    return jsonify({"error": "Bad request", "message": tags_err}), 400
            if "metadata" in item:
                meta_err = _validate_metadata(item["metadata"])
                if meta_err:
                    return jsonify({"error": "Bad request", "message": meta_err}), 400

        # Apply all updates
        updated = []
        for todo, item in todos_to_update:
            if "title" in item:
                todo.title = item["title"]
            if "completed" in item:
                todo.completed = item["completed"]
            if "tags" in item:
                todo.tags = item["tags"]
            if "metadata" in item:
                todo.metadata = item["metadata"]
            todo.version += 1
            todo.updated_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            updated.append(todo.to_dict())

    return jsonify({"updated": updated, "count": len(updated)}), 200


